            Err(e) => format!("error:{}", e.source),
        };
        let outcomes = std::mem::take(&mut *self.outcomes.lock().unwrap());
        Trace {
            status,
            outcomes,
            dedup_calls: self.dedup.take_calls(),
            tickets: self.tickets.load(Ordering::Relaxed) - tickets_before,
            ais: self.ais.take(),
        }
    }
}

